package com.mockarena.assessment.application; import com.mockarena.assessment.domain.*; import org.springframework.context.ApplicationEventPublisher; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class AttemptSubmissionApplicationService{private final AttemptRepository attempts;private final AttemptSubmitRequestRepository requests;private final ApplicationEventPublisher events;private final Clock clock=Clock.systemUTC();public AttemptSubmissionApplicationService(AttemptRepository a,AttemptSubmitRequestRepository r,ApplicationEventPublisher e){attempts=a;requests=r;events=e;}@Transactional public Submission submit(UUID id,UUID candidate,String key){if(key==null||key.isBlank()||key.length()>200)throw new IllegalArgumentException("Idempotency-Key is required");Attempt a=attempts.findByIdForUpdate(id).orElseThrow(AttemptNotFoundException::new);if(!a.candidateUserId().equals(candidate))throw new SecurityException("Attempt is not owned by current user");AttemptSubmitRequest replay=requests.findByAttemptIdAndIdempotencyKey(id,key.trim()).orElse(null);if(replay!=null){if(!replay.candidateUserId().equals(candidate))throw new IdempotencyKeyReusedException();return new Submission(a.id(),a.status().name(),replay.submittedAt(),a.deadlineAt());}Instant now=clock.instant();if(a.expireIfDue(now)){attempts.saveAndFlush(a);throw new IllegalStateException("Attempt is not in progress");}a.submit(now);attempts.saveAndFlush(a);requests.saveAndFlush(new AttemptSubmitRequest(UUID.randomUUID(),id,candidate,key.trim(),now));events.publishEvent(new AttemptSubmittedEvent(id));return new Submission(a.id(),a.status().name(),a.submittedAt(),a.deadlineAt());}public record Submission(UUID attemptId,String status,Instant submittedAt,Instant deadlineAt){}}
